package com.aiservice.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ai_knowledge_documents") public class AiKnowledgeDocumentEntity { @Id public UUID id; @Column(nullable=false,length=200) public String title; @Column(length=1000) public String description; @Column(name="original_file_name",nullable=false) public String originalFileName; @Column(name="content_type",nullable=false,length=120) public String contentType; @Column(name="file_size",nullable=false) public long fileSize; @Column(nullable=false,length=20) public String status; @Column(nullable=false) public boolean enabled; @Column(name="extracted_text",nullable=false,columnDefinition="TEXT") public String extractedText; @Column(name="created_by",nullable=false) public UUID createdBy; @Column(name="created_at",nullable=false) public Instant createdAt; @Column(name="updated_at",nullable=false) public Instant updatedAt; @Column(name="processing_error",length=1000) public String processingError; @Column(name="embedding_provider",nullable=false,length=80) public String embeddingProvider="LOCAL_HASH"; @Column(name="embedding_model",nullable=false,length=160) public String embeddingModel="unicode-token-v1"; @Column(name="embedding_dimension",nullable=false) public int embeddingDimension=128; @Column(name="embedding_normalization",nullable=false,length=40) public String embeddingNormalization="L2"; }
